import{_ as a,a0 as s,w as n,s as d,ao as p,I as r,x as t,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"何謂開源編程？ | LCTT x X-CMD","titleTemplate":false,"description":"何謂開源編程？ | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"何謂開源編程？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"何謂開源編程？ | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180308 What is open source programming","title":"何謂開源編程？","tag":"201809","desc":""},"relativePath":"201809/20180308 What is open source programming.md","filePath":"[post].md"}'),m={name:"201809/20180308 What is open source programming.md"};function u(f,e,g,b,T,h){const o=s("Link");return n(),d("div",null,[e[30]||(e[30]=p('<h1 id="何謂開源編程" tabindex="-1">何謂開源編程？ <a class="header-anchor" href="#何謂開源編程" aria-label="Permalink to “何謂開源編程？”">​</a></h1><blockquote><p>開源就是丟一些代碼到 GitHub 上。瞭解一下它是什麼，以及不是什麼？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/code_computer_development_programming.png?itok=4OM29-82" alt=""></p><p>最簡單的來説，開源編程就是編寫一些大家可以隨意取用、修改的代碼。但你肯定聽過關於 Go 語言的那個老笑話，説 Go 語言“簡單到看一眼就可以明白規則，但需要一輩子去學會運用它”。其實寫開源代碼也是這樣的。往 GitHub、Bitbucket、SourceForge 等網站或者是你自己的Blog或網站上丟幾行代碼不是難事，但想要卓有成效，還需要個人的努力付出和高瞻遠矚。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/u128651/floorgoban.jpeg?itok=r8gA5jOk" alt=""></p><h3 id="我們對開源編程的誤解" tabindex="-1">我們對開源編程的誤解 <a class="header-anchor" href="#我們對開源編程的誤解" aria-label="Permalink to “我們對開源編程的誤解”">​</a></h3><p>首先我要説清楚一點：把你的代碼放在 GitHub 的公開倉庫中並不意味着把你的代碼開源了。在幾乎全世界，根本不用創作者做什麼，只要作品形成，版權就隨之而生了。在創作者進行授權之前，只有作者可以行使版權相關的權力。未經創作者授權的代碼，不論有多少人在使用，都是一顆定時炸彈，只有愚蠢的人才會去用它。</p><p>有些創作者很善良，認為“很明顯我的代碼是免費提供給大家使用的。”，他也並不想起訴那些用了他的代碼的人，但這並不意味着這些代碼可以放心使用。不論在你眼中創作者們多麼善良，他們都 <em>有權力</em> 起訴任何使用、修改代碼，或未經明確授權就將代碼嵌入的人。</p><p>很明顯，你不應該在沒有指定開源許可證的情況下將你的源代碼發佈到網上然後期望別人使用它併為其做出貢獻。我建議你也儘量避免使用這種代碼，甚至疑似未授權的也不要使用。如果你開發了一個函數和例程，它和之前一個疑似未授權代碼很像，源代碼作者就可以對你就侵權提起訴訟。</p><p>舉個例子，Jill Schmill 寫了 AwesomeLib 然後未明確授權就把它放到了 GitHub 上，就算 Jill Schmill 不起訴任何人，只要她把 AwesomeLib 的完整版權都賣給 EvilCorp，EvilCorp 就會起訴之前違規使用這段代碼的人。這種行為就好像是埋下了計算機安全隱患，總有一天會為人所用。</p><p>沒有許可證的代碼的危險的，切記。</p><h3 id="選擇恰當的開源許可證" tabindex="-1">選擇恰當的開源許可證 <a class="header-anchor" href="#選擇恰當的開源許可證" aria-label="Permalink to “選擇恰當的開源許可證”">​</a></h3>',12)),r("p",null,[e[2]||(e[2]=t("假設你正要寫一個新程序，而且打算讓人們以開源的方式使用它，你需要做的就是選擇最貼合你需求的",-1)),l(o,{href:"https://opensource.com/tags/licensing"},{default:i(()=>[...e[0]||(e[0]=[t("許可證",-1)])]),_:1}),e[3]||(e[3]=t("。和宣傳中説的一樣，你可以從 GitHub 所支持的 ",-1)),l(o,{href:"https://choosealicense.com/"},{default:i(()=>[...e[1]||(e[1]=[t("choosealicense.com",-1)])]),_:1}),e[4]||(e[4]=t(" 開始。這個網站設計得像個簡單的問卷，特別方便快捷，點幾下就能找到合適的許可證。",-1))]),r("p",null,[e[7]||(e[7]=t("警示：在選擇許可證時不要過於自負，如果你選的是 ",-1)),l(o,{href:"https://choosealicense.com/licenses/apache-2.0/"},{default:i(()=>[...e[5]||(e[5]=[t("Apache 許可證",-1)])]),_:1}),e[8]||(e[8]=t("或者 ",-1)),l(o,{href:"https://choosealicense.com/licenses/gpl-3.0/"},{default:i(()=>[...e[6]||(e[6]=[t("GPLv3",-1)])]),_:1}),e[9]||(e[9]=t(" 這種廣為使用的許可證，人們很容易理解他們和你都有什麼權利，你也不需要請律師來排查其中的漏洞。你選擇的許可證使用的人越少，帶來的麻煩就越多。",-1))]),e[31]||(e[31]=r("p",null,[t("最重要的一點是： "),r("em",null,"千萬不要試圖自己製造許可證！"),t(" 自己製造許可證會給大家帶來更多的困惑和困擾，不要這樣做。如果在現有的許可證中確實找不到你需要的條款，你可以在現有的許可證中附加上你的要求，並且重點標註出來，提醒使用者們注意。")],-1)),r("p",null,[e[11]||(e[11]=t("我知道有些人會站出來説：“我才懶得管什麼許可證，我已經把代碼發到",-1)),e[12]||(e[12]=r("ruby",null,[t("公開領域"),r("rt",null,"public domain")],-1)),e[13]||(e[13]=t("了。”但問題是，公開領域的法律效力並不是受全世界認可的。在不同的國家，公開領域的效力和表現形式不同。在有些國家的政府管控下，你甚至不可以把自己的源代碼發到公開領域。萬幸，",-1)),l(o,{href:"https://choosealicense.com/licenses/unlicense/"},{default:i(()=>[...e[10]||(e[10]=[t("Unlicense",-1)])]),_:1}),e[14]||(e[14]=t(" 可以彌補這些漏洞，它語言簡潔，使用幾個詞清楚地描述了“就把它放到公開領域”，但其效力為全世界認可。",-1))]),e[32]||(e[32]=p('<h3 id="怎樣引入許可證" tabindex="-1">怎樣引入許可證 <a class="header-anchor" href="#怎樣引入許可證" aria-label="Permalink to “怎樣引入許可證”">​</a></h3><p>確定使用哪個許可證之後，你需要清晰而無疑義地指定它。如果你是在 GitHub、GitLab 或 BitBucket 這幾個網站發佈，你需要構建很多個文件夾，在根文件夾中，你應把許可證創建為一個以 <code>LICENSE.txt</code> 命名的明文文件。</p><p>創建 <code>LICENSE.txt</code> 這個文件之後還有其它事要做。你需要在每個重要文件的頭部添加註釋塊來申明許可證。如果你使用的是一個現有的許可證，這一步對你來説十分簡便。一個 <code># 項目名 (c)2018 作者名，GPLv3 許可證，詳情見 https://www.gnu.org/licenses/gpl-3.0.en.html</code> 這樣的註釋塊比隱約指代的許可證的效力要強得多。</p><p>如果你是要發佈在自己的網站上，步驟也差不多。先創建 <code>LICENSE.txt</code> 文件，放入許可證，再表明許可證出處。</p><h3 id="開源代碼的不同之處" tabindex="-1">開源代碼的不同之處 <a class="header-anchor" href="#開源代碼的不同之處" aria-label="Permalink to “開源代碼的不同之處”">​</a></h3><p>開源代碼和專有代碼的一個主要區別是開源代碼寫出來就是為了給別人看的。我是個 40 多歲的系統管理員，已經寫過許許多多的代碼。最開始我寫代碼是為了工作，為了解決公司的問題，所以其中大部分代碼都是專有代碼。這種代碼的目的很簡單，只要能在特定場合通過特定方式發揮作用就行。</p><p>開源代碼則大不相同。在寫開源代碼時，你知道它可能會被用於各種各樣的環境中。也許你的用例的環境條件很侷限，但你仍舊希望它能在各種環境下發揮理想的效果。不同的人使用這些代碼時會出現各種用例，你會看到各類衝突，還有你沒有考慮過的思路。雖然代碼不一定要滿足所有人，但至少應該得體地處理他們遇到的問題，就算解決不了，也可以轉換回常見的邏輯，不會給使用者添麻煩。（例如“第 583 行出現零除錯誤”就不能作為錯誤地提供命令列參數的響應結果）</p><p>你的源代碼也可能逼瘋你，尤其是在你一遍又一遍地修改錯誤的函數或是子過程後，終於出現了你希望的結果，這時你不會嘆口氣就繼續下一個任務，你會把過程清理乾淨，因為你不會願意別人看出你一遍遍嘗試的痕跡。比如你會把 <code>$variable</code>、<code>$lol</code> 全都換成有意義的 <code>$iterationcounter</code> 和 <code>$modelname</code>。這意味着你要認真專業地進行註釋（儘管對於你所處的背景知識熱度來説它並不難懂），因為你期望有更多的人可以使用你的代碼。</p><p>這個過程難免有些痛苦沮喪，畢竟這不是你常做的事，會有些不習慣。但它會使你成為一位更好的程序員，也會讓你的代碼昇華。即使你的項目只有你一位貢獻者，清理代碼也會節約你後期的很多工作，相信我一年後你再看你的 app 代碼時，你會慶幸自己寫下的是 <code>$modelname</code>，還有清晰的註釋，而不是什麼不知名的數列，甚至連 <code>$lol</code> 也不是。</p><h3 id="你並不是為你一人而寫" tabindex="-1">你並不是為你一人而寫 <a class="header-anchor" href="#你並不是為你一人而寫" aria-label="Permalink to “你並不是為你一人而寫”">​</a></h3><p>開源的真正核心並不是那些代碼，而是社區。更大的社區的項目維持時間更長，也更容易為人們所接受。因此不僅要加入社區，還要多多為社區發展貢獻思路，讓自己的項目能夠為社區所用。</p><p>蝙蝠俠為了完成目標暗中獨自花了很大功夫，你用不着這樣，你可以登錄 Twitter、Reddit，或者給你項目的相關人士發郵件，發佈你正在籌備新項目的消息，仔細聊聊項目的設計初衷和你的計劃，讓大家一起幫忙，向大家徵集數據輸入，類似的使用案例，把這些信息整合起來，用在你的代碼裏。你不用接受所有的建議和請求，但你要對它有個大概把握，這樣在你之後完善時可以躲過一些陷阱。</p><p>發佈了首次通告這個過程還不算完整。如果你希望大家能夠接受你的作品並且使用它，你就要以此為初衷來設計。公眾説不定可以幫到你，你不必對公開這件事如臨大敵。所以不要閉門造車，既然你是為大家而寫，那就開設一個真實、公開的項目，想像你在社區的幫助和監督下，認真地一步步完成它。</p><h3 id="建立項目的方式" tabindex="-1">建立項目的方式 <a class="header-anchor" href="#建立項目的方式" aria-label="Permalink to “建立項目的方式”">​</a></h3><p>你可以在 GitHub、GitLab 或 BitBucket 上免費註冊賬號來管理你的項目。註冊之後，創建知識庫，建立 <code>README</code> 文件，分配一個許可證，一步步寫入代碼。這樣可以幫你建立好習慣，讓你之後和現實中的團隊一起工作時，也能目的清晰地朝着目標穩妥地開展工作。這樣你做得越久，就越有興趣 —— 通常會有用户先對你的項目產生興趣。</p><p>用户會開始提一些問題，這會讓你開心也會讓你不爽，你應該親切禮貌地對待他們，就算他們很多人對項目有很多誤解甚至根本不知道你的項目做的是什麼，你也應該禮貌專業地對待。一方面，你可以引導他們，讓他們瞭解你在幹什麼。另一方面，他們也會慢慢地將你帶入更大的社區。</p><p>如果你的項目很受用户青睞，總會有高級開發者出現，並表示出興趣。這也許是好事，也可能激怒你。最開始你可能只會做簡單的問題修復，但總有一天你會收到拉取請求，有可能是硬編碼或特殊用例（可能會讓項目變得難以維護），它可能改變你項目的作用域，甚至改變你項目的初衷。你需要學會分辨哪個有貢獻，根據這個決定合併哪個，婉拒哪個。</p><h3 id="我們為什麼要開源" tabindex="-1">我們為什麼要開源？ <a class="header-anchor" href="#我們為什麼要開源" aria-label="Permalink to “我們為什麼要開源？”">​</a></h3><p>開源聽起來任務繁重，它也確實是這樣。但它對你也有很多好處。它可以在無形之中磨練你，讓你寫出純淨持久的代碼，也教會你與人溝通，團隊協作。對於一個志向遠大的專業開發者來説，它是最好的簡歷素材。你的未來僱主很有可能點開你的倉庫，瞭解你的能力範圍；而社區項目的開發者也有可能給你帶來工作。</p><p>最後，為開源工作，意味着個人的提升，因為你在做的事不是為了你一個人，這比養活自己重要得多。</p><hr>',21)),r("p",null,[e[16]||(e[16]=t("via: ",-1)),l(o,{href:"https://opensource.com/article/18/3/what-open-source-programming"},{default:i(()=>[...e[15]||(e[15]=[t("https://opensource.com/article/18/3/what-open-source-programming",-1)])]),_:1})]),r("p",null,[e[21]||(e[21]=t("作者：",-1)),l(o,{href:"https://opensource.com/users/jim-salter"},{default:i(()=>[...e[17]||(e[17]=[t("Jim Salter",-1)])]),_:1}),e[22]||(e[22]=t(" 譯者：",-1)),l(o,{href:"https://github.com/Valoniakim"},{default:i(()=>[...e[18]||(e[18]=[t("Valoniakim",-1)])]),_:1}),e[23]||(e[23]=t(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[19]||(e[19]=[t("wxy",-1)])]),_:1}),e[24]||(e[24]=t("、",-1)),l(o,{href:"https://github.com/pityonline"},{default:i(()=>[...e[20]||(e[20]=[t("pityonline",-1)])]),_:1})]),r("p",null,[e[27]||(e[27]=t("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[25]||(e[25]=[t("LCTT",-1)])]),_:1}),e[28]||(e[28]=t(" 原創編譯，",-1)),l(o,{href:"https://linux.cn/"},{default:i(()=>[...e[26]||(e[26]=[t("Linux中國",-1)])]),_:1}),e[29]||(e[29]=t(" 榮譽推出",-1))])])}const L=a(m,[["render",u]]);export{k as __pageData,L as default};
